/** A person's claims: a form that adds a claim or edits one, and the claims newest first, each
 *  with its status, its due (fixed when settled, else at the person's `grade`'s rate in force on the
 *  claim's date; none when there is no such rate)
 *  who opened it, and buttons that change its status (the user who opened a claim cannot settle it). */
export function PersonClaims({ sheetId, user, personId, claims, grade, rates }: {
  sheetId: string; user: string; personId: number; claims: Claim[]; grade: string; rates: Rate[] | undefined;
}) {
  const queryClient = useQueryClient();
  const [form, setForm] = useState<ClaimInput>(EMPTY);
  const [editing, setEditing] = useState<number | null>(null);

  const save = useMutation({
    mutationFn: (v: { id: number | null; input: ClaimInput }) =>
      v.id === null ? addClaim(sheetId, user, personId, v.input) : updateClaim(sheetId, user, v.id, v.input),
    onSuccess: () => {
      setForm(EMPTY);
      setEditing(null);
      return queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
  });

  // The claim whose last status change was refused; cleared by the next action on any claim here.
  const move = useMutation({
    mutationFn: (v: { id: number; action: ClaimAction }) => moveClaim(sheetId, user, v.id, v.action),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
  });

  const act = (id: number, action: ClaimAction) => {
    move.reset();
    move.mutate({ id, action });
  };

  const change = (patch: Partial<ClaimInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    save.reset();
  };

  const open = (c: Claim) => {
    setForm({ amount: c.amount, date: c.date, note: c.note });
    setEditing(c.id);
    save.reset();
    move.reset();
  };

  const cancel = () => {
    setForm(EMPTY);
    setEditing(null);
    save.reset();
  };

  return (
    <div>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          save.reset();
          save.mutate({ id: editing, input: form });
        }}
      >
        <input data-testid="claim-form-amount" placeholder="Amount" value={form.amount}
          onChange={(e) => change({ amount: e.target.value })} />{' '}
        <input type="date" data-testid="claim-form-date" value={form.date}
          onChange={(e) => change({ date: e.target.value })} />{' '}
        <input data-testid="claim-form-note" placeholder="Note" value={form.note}
          onChange={(e) => change({ note: e.target.value })} />{' '}
        <button type="submit" data-testid="claim-form-submit" disabled={save.isPending}>
          {editing === null ? 'Add claim' : 'Save claim'}
        </button>
        {save.isError && (
          <span data-testid="claim-form-error">A claim needs an amount of 0.00 or more with up to two decimals.</span>
        )}
      </form>
      <table>
        <tbody>
          {claims.map((c) => (
            <tr key={c.id} data-testid={`claim-row-${c.id}`}>
              <td data-testid="claim-number">{c.number ?? ''}</td>
              <td data-testid="claim-amount">{Number(c.amount).toFixed(2)}</td>
              <td data-testid="claim-date">{c.date}</td>
              <td data-testid="claim-note">{c.note}</td>
              <td data-testid="claim-due">{showDue(claimDue(c, rates, grade))}</td>
              <td data-testid="claim-status">{c.status}</td>
              <td data-testid="claim-opened-by">{c.openedBy ?? ''}</td>
              <td>
                {(['open', 'settle', 'void'] as const).map((a) => (
                  <button key={a} type="button" data-testid={`claim-${a}`} disabled={move.isPending}
                    onClick={() => act(c.id, a)}>
                    {a === 'open' ? 'Open' : a === 'settle' ? 'Settle' : 'Void'}
                  </button>
                ))}{' '}
                <button type="button" data-testid="claim-edit" onClick={() => open(c)}>
                  Edit
                </button>
                {editing === c.id && (
                  <button type="button" data-testid="claim-cancel" onClick={cancel}>
                    Cancel
                  </button>
                )}
                {move.isError && move.variables?.id === c.id && (
                  <span data-testid="claim-error">{c.status === 'OPEN' && move.variables.action === 'settle'
                    ? 'The user who opened a claim cannot settle it.'
                    : `A ${c.status} claim cannot be ${move.variables.action === 'open'
                      ? 'opened' : move.variables.action === 'settle' ? 'settled' : 'voided'}.`}</span>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { GRADES } from '../people/api';
import { useSheetToday } from '../sheet/api';
import { listRates, rateByGrade, ratesKey, setRate, type RateInput } from './api';

const EMPTY: RateInput = { grade: 'A', pct: '', from: '' };

/** The sheet's rates: a form that sets one (from a from-date, or from the beginning of time),
 *  each grade's rate in force on the sheet's today, and every rate by grade and from-date. */
export function Rates({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const rates = useQuery({ queryKey: ratesKey(sheetId), queryFn: () => listRates(sheetId) });
  const byGrade = rateByGrade(rates.data, useSheetToday(sheetId, user));
  const [form, setForm] = useState<RateInput>(EMPTY);

  const save = useMutation({
    mutationFn: (input: RateInput) => setRate(sheetId, user, input),
    onSuccess: () => {
      setForm((f) => ({ ...f, pct: '', from: '' }));
      return queryClient.invalidateQueries({ queryKey: ratesKey(sheetId) });
    },
  });

  const change = (patch: Partial<RateInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    save.reset();
  };

  return (
    <section>
      <h3>Rates</h3>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          save.reset();
          save.mutate(form);
        }}
      >
        <label>
          Grade{' '}
          <select data-testid="rate-form-grade" value={form.grade} onChange={(e) => change({ grade: e.target.value })}>
            {GRADES.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <label>
          Percent{' '}
          <input data-testid="rate-form-pct" value={form.pct} onChange={(e) => change({ pct: e.target.value })} />
        </label>{' '}
        <label>
          From{' '}
          <input type="date" data-testid="rate-form-from" value={form.from}
            onChange={(e) => change({ from: e.target.value })} />
        </label>{' '}
        <button type="submit" data-testid="rate-form-submit" disabled={save.isPending}>
          Set rate
        </button>
        {save.isError && (
          <span data-testid="rate-form-error">A rate needs a percent of 0.00 or more with up to two decimals, and a from-date that is a date or blank.</span>
        )}
      </form>
      <table>
        <tbody>
          {GRADES.map((g) => (
            <tr key={g}>
              <td>{g}</td>
              <td data-testid={`rate-current-${g}`}>
                {byGrade.has(g) ? <span data-testid="rate-pct">{byGrade.get(g)}</span> : 'n/a'}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <table>
        <tbody>
          {(rates.data ?? []).map((r) => (
            <tr key={`${r.grade}-${r.from ?? 'start'}`} data-testid={`rate-row-${r.grade}-${r.from ?? 'start'}`}>
              <td>{r.grade}</td>
              <td>{r.from === null ? 'From the start' : `From ${r.from}`}</td>
              <td>
                <span data-testid="rate-pct">{r.pct}</span>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { setSheetToday, sheetKey, type Sheet } from './api';

/** The sheet's today, shown and changeable. Every date on the sheet goes by it. */
export function SheetToday({ sheet, user }: { sheet: Sheet; user: string }) {
  const queryClient = useQueryClient();
  const [date, setDate] = useState('');
  const save = useMutation({
    mutationFn: (today: string) => setSheetToday(sheet.id, user, today),
    onSuccess: (updated) => {
      // Everything under the sheet may depend on its today: re-read it all.
      queryClient.setQueryData(sheetKey(sheet.id), updated);
      queryClient.invalidateQueries({
        queryKey: sheetKey(sheet.id),
        predicate: (q) => q.queryKey.length > 2,
      });
    },
  });

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        save.reset();
        save.mutate(date.trim());
      }}
    >
      Today <span data-testid="sheet-today">{sheet.today}</span>{' '}
      <input
        type="date"
        data-testid="sheet-today-input"
        value={date}
        onChange={(e) => {
          setDate(e.target.value);
          save.reset();
        }}
      />{' '}
      <button type="submit" data-testid="sheet-today-save" disabled={save.isPending}>
        Set today
      </button>
      {save.isError && <span data-testid="sheet-error">That is not a date.</span>}
    </form>
  );
}
import { useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { useSheetId } from '../session/session';
import { sheetKey } from './api';

/** Choose a sheet by typing its id and loading it. */
export function SheetPicker() {
  const queryClient = useQueryClient();
  const [, setSheetId] = useSheetId();
  const [id, setId] = useState('');
  const [error, setError] = useState(false);

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        const trimmed = id.trim();
        if (!trimmed) {
          setError(true);
          return;
        }
        // Loading a sheet re-reads it from the store, even when it was on screen before.
        queryClient.removeQueries({ queryKey: sheetKey(trimmed) });
        setSheetId(trimmed);
      }}
    >
      <label>
        Sheet{' '}
        <input
          data-testid="sheet-id-input"
          value={id}
          onChange={(e) => {
            setId(e.target.value);
            setError(false);
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="sheet-load">
        Load
      </button>
      {error && <span data-testid="sheet-load-error">Type a sheet id to load.</span>}
    </form>
  );
}
import { useState } from 'react';
import { useUser } from './session';

/** Sign in by typing a name; there is no password. */
export function SignIn() {
  const [, setUser] = useUser();
  const [name, setName] = useState('');
  const [error, setError] = useState(false);

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        const trimmed = name.trim();
        if (!trimmed) {
          setError(true);
          return;
        }
        setUser(trimmed);
      }}
    >
      <label>
        Name{' '}
        <input
          data-testid="signin-name"
          value={name}
          onChange={(e) => {
            setName(e.target.value);
            setError(false);
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="signin-submit">
        Sign in
      </button>
      {error && <span data-testid="signin-error">Type a name to sign in.</span>}
    </form>
  );
}
